import{_ as a,C as s,o as n,c as i,aj as e,G as o}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Job Tracker","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/data-transfer/job-tracker.md","filePath":"2.0/data-transfer/job-tracker.md","lastUpdated":1781078920000}'),d={name:"2.0/data-transfer/job-tracker.md"};function l(h,t,c,p,g,u){const r=s("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="job-tracker" tabindex="-1">Job Tracker <a class="header-anchor" href="#job-tracker" aria-label="Permalink to &quot;Job Tracker&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Data Transfer → <strong>Job Tracker</strong><strong>URL:</strong> <code>/admin/data-transfer/job-tracker</code></p></blockquote><p>The <strong>Job Tracker</strong> is the central monitoring page for every import and export job UnoPim runs. When you click <em>Import Now</em> or <em>Export Now</em> from a profile, or watch a background job fire off, this is the screen that shows you what&#39;s happening right now, what&#39;s finished, and what — if anything — went wrong.</p><h2 id="what-is-the-job-tracker" tabindex="-1">What is the Job Tracker? <a class="header-anchor" href="#what-is-the-job-tracker" aria-label="Permalink to &quot;What is the Job Tracker?&quot;">​</a></h2><p>A single real-time view of every data-transfer job in the system. Instead of hunting through import and export listings separately, you open one page and see:</p><ul><li><strong>Every job&#39;s status</strong> — queued, processing, complete, failed, cancelled, paused.</li><li><strong>Live progress</strong> — current step in the pipeline, count of records created / updated / deleted so far.</li><li><strong>Controls</strong> — pause, resume, or cancel an in-flight job.</li><li><strong>Logs and artefacts</strong> — download the job log or the exported file once the run finishes.</li></ul>',6)),o(r,{src:"/assets/2.0/images/data-transfer/tracker.png",alt:"Job Tracker"}),t[1]||(t[1]=e('<h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>Every import and export runs as a queued job. The moment you launch one, UnoPim:</p><ol><li>Creates a <strong>job record</strong> with a unique ID, status <code>Queued</code>, and the configuration that was submitted.</li><li>As the queue worker picks it up, the job moves through a fixed <strong>step pipeline</strong> — each step updates the record.</li><li>The Job Tracker page subscribes to those updates and repaints the progress UI live (no refresh needed).</li><li>When the job lands in a terminal state (<code>Complete</code>, <code>Failed</code>, <code>Cancelled</code>), the log file and any produced artefacts become downloadable from the tracker.</li></ol><p>Because every step writes to the same record, you can navigate away from the tracker mid-run and come back later — the page restores the current state from the database.</p><h2 id="job-statuses" tabindex="-1">Job statuses <a class="header-anchor" href="#job-statuses" aria-label="Permalink to &quot;Job statuses&quot;">​</a></h2><p>Each row in the tracker shows the job&#39;s current status as a coloured chip:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is in the queue, waiting for a worker.</td></tr><tr><td><strong>Validating</strong> / <strong>Validated</strong></td><td>File is being validated, or validation finished successfully and the import is ready to run.</td></tr><tr><td><strong>Processing</strong></td><td>A worker has picked it up and the pipeline is advancing.</td></tr><tr><td><strong>Paused</strong></td><td>You stopped it mid-run; state is preserved and it can be resumed.</td></tr><tr><td><strong>Completed</strong></td><td>All steps finished successfully.</td></tr><tr><td><strong>Failed</strong></td><td>A step errored; see the log for details.</td></tr><tr><td><strong>Cancelled</strong></td><td>You stopped it permanently; cannot be resumed.</td></tr></tbody></table><h2 id="tracker-listing-columns" tabindex="-1">Tracker listing columns <a class="header-anchor" href="#tracker-listing-columns" aria-label="Permalink to &quot;Tracker listing columns&quot;">​</a></h2><p>The tracker is a datagrid; one row per job:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>Auto-incremented job ID. Matches the <code>#n</code> suffix on notifications (e.g., <em>Import #15</em>).</td></tr><tr><td><strong>Job</strong></td><td>The profile code (e.g., <code>product_export</code>, <code>category_import</code>).</td></tr><tr><td><strong>Type</strong></td><td>What&#39;s being transferred — <code>Products</code> or <code>Categories</code>.</td></tr><tr><td><strong>Job Type</strong></td><td>How the job was triggered — <code>import</code>, <code>export</code>, or <code>system</code> (scheduled, bulk, or AI-Agent-initiated).</td></tr><tr><td><strong>Status</strong></td><td>Current state (see table above).</td></tr><tr><td><strong>User</strong></td><td>The admin who started the job.</td></tr><tr><td><strong>Started at</strong> / <strong>Completed at</strong></td><td>Timestamps.</td></tr><tr><td><strong>Actions</strong></td><td><strong>Eye icon</strong> — opens the job detail page where the step pipeline, live progress, and Pause / Resume / Cancel controls are shown.</td></tr></tbody></table>',10)),o(r,{src:"/assets/2.0/images/data-transfer/tracker.png",alt:"Job Tracker listing"}),t[2]||(t[2]=e('<h2 id="system-jobs-and-ai-agent-triggered-jobs" tabindex="-1">System jobs and AI-Agent-triggered jobs <a class="header-anchor" href="#system-jobs-and-ai-agent-triggered-jobs" aria-label="Permalink to &quot;System jobs and AI-Agent-triggered jobs&quot;">​</a></h2><p>Not every entry in the tracker comes from a manual import / export. Jobs fall into three categories, shown in the <strong>Job Type</strong> column:</p><table tabindex="0"><thead><tr><th>Job Type</th><th>Where it comes from</th></tr></thead><tbody><tr><td><code>import</code></td><td>A manual run from <strong>Data Transfer → Imports</strong>.</td></tr><tr><td><code>export</code></td><td>A manual run from <strong>Data Transfer → Exports</strong>, or a <strong>Quick Export</strong> from the Products listing.</td></tr><tr><td><code>system</code></td><td>A background job — bulk product updates, scheduled catalog quality scans, auto-enrichment runs, or exports the AI Agent produced on your behalf. AI-Agent-initiated jobs show up with names like <code>ai-agent-export-…</code>.</td></tr></tbody></table><p>All three share the same lifecycle, status chips, logs, and Pause / Resume / Cancel controls — the only difference is how they were started.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you see a <code>system</code> job you don&#39;t recognise, click the eye icon to open the detail page. The detail view shows the user that triggered the chain and, for AI-Agent jobs, the chat message that produced it.</p></div><h2 id="step-pipelines-on-the-job-detail-page" tabindex="-1">Step pipelines (on the job detail page) <a class="header-anchor" href="#step-pipelines-on-the-job-detail-page" aria-label="Permalink to &quot;Step pipelines (on the job detail page)&quot;">​</a></h2><p>Click the <strong>eye icon</strong> on a row in the tracker to open the job detail page. The detail page visualises the job as a horizontal step pipeline. The exact steps depend on the job type:</p><h3 id="import-pipeline" tabindex="-1">Import pipeline <a class="header-anchor" href="#import-pipeline" aria-label="Permalink to &quot;Import pipeline&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is waiting for a worker.</td></tr><tr><td><strong>Validating</strong></td><td>File is being validated against the import rules.</td></tr><tr><td><strong>Importing</strong></td><td>Records are being created / updated / deleted in the database.</td></tr><tr><td><strong>Indexing</strong></td><td>Elasticsearch indexes are being updated so products are searchable.</td></tr><tr><td><strong>Complete</strong></td><td>Import finished successfully.</td></tr></tbody></table>',9)),o(r,{src:"/assets/2.0/images/data-transfer/import-progress.png",alt:"Import Progress"}),t[3]||(t[3]=e('<h3 id="export-pipeline" tabindex="-1">Export pipeline <a class="header-anchor" href="#export-pipeline" aria-label="Permalink to &quot;Export pipeline&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is waiting for a worker.</td></tr><tr><td><strong>Validating</strong></td><td>Export configuration is being validated.</td></tr><tr><td><strong>Exporting</strong></td><td>Records are being written to the output file.</td></tr><tr><td><strong>Complete</strong></td><td>Export finished successfully.</td></tr></tbody></table>',2)),o(r,{src:"/assets/2.0/images/data-transfer/export-progress.png",alt:"Export Progress"}),t[4]||(t[4]=e('<p>Each completed step renders with a green checkmark. A failed step renders red and the pipeline stops there — subsequent steps are skipped.</p><h2 id="details-shown-for-each-job" tabindex="-1">Details shown for each job <a class="header-anchor" href="#details-shown-for-each-job" aria-label="Permalink to &quot;Details shown for each job&quot;">​</a></h2><p>Below the pipeline, the tracker shows:</p><ul><li><strong>Success / Error message</strong> — <em>&quot;Job completed successfully&quot;</em> plus total duration, or the specific error that stopped the run (e.g., <em>&quot;Required columns not found: code&quot;</em>).</li><li><strong>Records Created / Updated / Deleted</strong> — exact counts of what changed.</li><li><strong>Total Duration</strong> — how long the job took from queued to terminal state.</li><li><strong>Download log</strong> — full import/export log for offline review.</li><li><strong>Download Exported Files</strong> <em>(exports only)</em> — the CSV/XLS/XLSX produced by the run.</li></ul><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><h3 id="pause" tabindex="-1">Pause <a class="header-anchor" href="#pause" aria-label="Permalink to &quot;Pause&quot;">​</a></h3><p>During a <code>Processing</code> run, click <strong>Pause</strong> to temporarily halt the job. UnoPim freezes the job state at the current batch — no records are lost, nothing rolls back, and the queue worker moves on to other work.</p><h3 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h3><p>For a <code>Paused</code> job, click <strong>Resume</strong> to continue from the next batch. The job picks up exactly where it left off — already-processed records are not reprocessed.</p><h3 id="cancel" tabindex="-1">Cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;Cancel&quot;">​</a></h3><p>Click <strong>Cancel</strong> to stop a job permanently. The job moves to the <code>Cancelled</code> state and cannot be resumed. Records already written by earlier steps are <strong>not</strong> rolled back — if you need to undo them, run a cleanup import.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pause is the right choice during peak hours on a large job. Cancel is for <em>&quot;this import had the wrong file&quot;</em> situations — once you cancel, you start over from the listing page.</p></div><h2 id="opening-the-job-tracker" tabindex="-1">Opening the Job Tracker <a class="header-anchor" href="#opening-the-job-tracker" aria-label="Permalink to &quot;Opening the Job Tracker&quot;">​</a></h2><p>Three common entry points:</p><ol><li><strong>From the admin sidebar</strong> — click <strong>Data Transfer → Job Tracker</strong>.</li><li><strong>After launching a job</strong> — the <em>Import Now</em> / <em>Export Now</em> button redirects you straight to the tracker for the job you just started.</li><li><strong>From the Dashboard</strong> — the <strong>Data Transfer</strong> widget lists recent jobs and a <em>&quot;View All Jobs&quot;</em> link goes to the tracker.</li></ol><h2 id="how-the-tracker-relates-to-imports-and-exports" tabindex="-1">How the tracker relates to imports and exports <a class="header-anchor" href="#how-the-tracker-relates-to-imports-and-exports" aria-label="Permalink to &quot;How the tracker relates to imports and exports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Role</th></tr></thead><tbody><tr><td><strong><a href="./import.html">Import</a></strong></td><td>Define an import profile (code, type, file, validation strategy, action mode).</td></tr><tr><td><strong><a href="./export.html">Export</a></strong></td><td>Define an export profile (code, type, file format, media).</td></tr><tr><td><strong>Job Tracker</strong> (this page)</td><td>Monitor the runs those profiles produce — status, progress, logs, artefacts.</td></tr></tbody></table><p>Profiles are <em>reusable configurations</em>. Every time you hit <em>Import Now</em> or <em>Export Now</em> on a profile, a new job is created and surfaced in the Job Tracker.</p><h2 id="background-processing" tabindex="-1">Background processing <a class="header-anchor" href="#background-processing" aria-label="Permalink to &quot;Background processing&quot;">​</a></h2><p>Jobs run on the Laravel queue worker. If you don&#39;t see queued jobs progressing, make sure a worker is running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:listen</span></span></code></pre></div><p>For production, run the worker as a managed service (systemd, Supervisor, …) so it stays up across reboots.</p>',22))])}const f=a(d,[["render",l]]);export{m as __pageData,f as default};
